svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-ch2)"/>`;

// Canopy
for (let i = 0; i < 14; i++) {
  const cx2 = w*(-0.05+i*0.08);
  const cy2 = h*0.02+Math.sin(i*1.7)*h*0.025;
