  svg += `<circle cx="${cx2+sw3}" cy="${cy2}" r="${cr}" fill="${isN?'#0A1A0A':'#1A4A1A'}" opacity="0.55"/>`;
}

// Light beams
for (let i = 0; i < 4; i++) {
  const bx2 = w*(0.12+i*0.22)+Math.sin(mt*0.3+i*1.5)*8;
  const bOp = 0.035+Math.sin(mt*0.5+i*0.7)*0.02;
  const bCol = isN?'rgba(180,200,255,':'rgba(255,240,180,';
  svg += `<polygon points="${bx2-2},0 ${bx2+2},0 ${bx2+20},${h*0.65} ${bx2-12},${h*0.65}" fill="${bCol}${bOp})"/>`;
}

// Forest floor
svg += `<path d="M0 ${bY-12} Q${w*0.12} ${bY-22} ${w*0.25} ${bY-8} Q${w*0.4} ${bY-18} ${w*0.55} ${bY-10} Q${w*0.7} ${bY-20} ${w*0.85} ${bY-6} Q${w*0.95} ${bY-15} ${w} ${bY-8} L${w} ${h} L0 ${h} Z" fill="${sc.ground}" stroke="#1A3A1A" stroke-width="${ol*0.5}"/>`;
for (let i = 0; i < 18; i++) {
  const mx = w*(i/18);
  const my = bY-3+Math.sin(i*1.9)*6;
  svg += `<ellipse cx="${mx}" cy="${my}" rx="${7+Math.sin(i*1.3)*3}" ry="2.5" fill="#3A6A3A" opacity="0.25"/>`;
}

// ── BIG TREES ──
const trees = [[w*0.05,95],[w*0.32,115],[w*0.62,100],[w*0.88,90]];
for (let t = 0; t < 4; t++) {
  const ttx2 = trees[t][0], tth2 = trees[t][1];
  const tsw = Math.sin(mt*0.35+t*1.2)*3;
  svg += `<path d="M${ttx2-6} ${bY-3} Q${ttx2-3+tsw*0.3} ${bY-tth2*0.5} ${ttx2+tsw} ${bY-tth2}" fill="none" stroke="#4A3020" stroke-width="${11+t}" stroke-linecap="round"/>`;
  for (let r = 0; r < 3; r++) {
    const rd = r-1;
    svg += `<path d="M${ttx2+rd*4} ${bY-3} Q${ttx2+rd*16} ${bY+2} ${ttx2+rd*20} ${bY+4}" fill="none" stroke="#3A2818" stroke-width="2.5" stroke-linecap="round" opacity="0.5"/>`;
  }
  for (let c = 0; c < 5; c++) {
    const lcx = ttx2+Math.sin(c*1.1+t)*25+tsw;
    const lcy = bY-tth2-3+Math.cos(c*0.9+t)*15;
    const lcr = 16+Math.sin(c*2.3+t*0.7)*7;
    svg += `<circle cx="${lcx}" cy="${lcy}" r="${lcr}" fill="${isN?'#0E2A0E':'#2A5A2A'}" stroke="${isN?'#0A1A0A':'#1A4A1A'}" stroke-width="${ol*0.3}" opacity="0.75"/>`;
  }
}

// ── Mushrooms (glowing path markers) ──
const mush = [[w*0.15,bY+3],[w*0.28,bY+8],[w*0.42,bY+1],[w*0.55,bY+6],[w*0.7,bY+10],[w*0.85,bY+4]];
const mCols = ['#FF6B9D','#00CED1','#9370DB','#FF8C42','#4ECDC4','#DA70D6'];
for (let i = 0; i < 6; i++) {
  const mxp = mush[i][0], myp = mush[i][1];
  const mh2 = 7+Math.sin(i*2.1)*2;
  const gP = Math.sin(mt*1.5+i*1.1)*0.5+0.5;
  svg += `<rect x="${mxp-1.5}" y="${myp-mh2}" width="3" height="${mh2}" rx="1" fill="#E8D8C0"/>`;
  svg += `<ellipse cx="${mxp}" cy="${myp-mh2}" rx="${6+Math.sin(i*1.7)*2}" ry="${3.5+Math.sin(i*1.3)}" fill="${mCols[i]}"/>`;
  svg += `<circle cx="${mxp-2}" cy="${myp-mh2-1}" r="0.8" fill="#FFF" opacity="0.5"/>`;
  svg += `<circle cx="${mxp}" cy="${myp-mh2}" r="${10+gP*5}" fill="${mCols[i]}" opacity="${0.03+gP*0.04}"/>`;
}

// ── Enchanted stream ──
const stY = bY+22;
for (let i = 0; i < 3; i++) {
  const sWave = Math.sin(mt*1.2+i*0.8)*8;
  svg += `<path d="M0 ${stY+i*3} Q${w*0.15+sWave} ${stY+i*3-3} ${w*0.3} ${stY+i*3+1} Q${w*0.5-sWave} ${stY+i*3-2} ${w*0.7} ${stY+i*3+1} T${w} ${stY+i*3}" fill="none" stroke="rgba(120,190,230,${0.18+Math.sin(mt*0.8+i)*0.08})" stroke-width="${2.5-i*0.4}"/>`;
}
for (let i = 0; i < 6; i++) {
  const skx = w*(0.08+i*0.15)+Math.sin(mt*0.5+i*1.3)*4;
  svg += `<circle cx="${skx}" cy="${stY+Math.sin(i*2.1)*2}" r="1" fill="#FFF" opacity="${0.3+Math.sin(mt*2+i*0.9)*0.25}"/>`;
}

// ── Flowers ──
for (let i = 0; i < 10; i++) {
  const flx = w*(0.03+i*0.1);
  const fly = bY-1+Math.sin(i*1.8)*4;
  const flSw = Math.sin(mt*0.9+i*0.7)*2;
  const flC = ['#FF69B4','#DDA0DD','#87CEEB','#98FB98','#FFB6C1','#E6E6FA','#FFA07A','#20B2AA','#F0E68C','#DB7093'][i];
  svg += `<line x1="${flx}" y1="${fly}" x2="${flx+flSw}" y2="${fly-7}" stroke="#2A5A2A" stroke-width="1" stroke-linecap="round"/>`;
  svg += `<circle cx="${flx+flSw}" cy="${fly-8}" r="2.5" fill="${flC}" opacity="0.75"/>`;
}

// ═══ CHARACTERS ═══

// ── Wise Owl (on branch of middle-left tree) ──
const owlX = trees[1][0]+15;
const owlY = bY-trees[1][1]*0.48-8;
const owlBlink = Math.sin(mt*0.8)>0.93?0:1;
// Branch
svg += `<line x1="${trees[1][0]+3}" y1="${owlY+12}" x2="${owlX+8}" y2="${owlY+10}" stroke="#5A4030" stroke-width="4" stroke-linecap="round"/>`;
svg += `<ellipse cx="${owlX}" cy="${owlY+2}" rx="8" ry="10" fill="#8B6B4A" stroke="#6B4B2A" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${owlX}" cy="${owlY-9}" r="7" fill="#9B7B5A" stroke="#6B4B2A" stroke-width="${ol*0.4}"/>`;
svg += `<polygon points="${owlX-5},${owlY-14} ${owlX-3},${owlY-21} ${owlX-1},${owlY-14}" fill="#7B5B3A"/>`;
svg += `<polygon points="${owlX+1},${owlY-14} ${owlX+3},${owlY-21} ${owlX+5},${owlY-14}" fill="#7B5B3A"/>`;
if (owlBlink) {
  svg += `<circle cx="${owlX-3}" cy="${owlY-10}" r="3.5" fill="#FFD700" stroke="#DAA520" stroke-width="0.5"/>`;
  svg += `<circle cx="${owlX+3}" cy="${owlY-10}" r="3.5" fill="#FFD700" stroke="#DAA520" stroke-width="0.5"/>`;
  svg += `<circle cx="${owlX-3}" cy="${owlY-10}" r="1.5" fill="#222"/>`;
  svg += `<circle cx="${owlX+3}" cy="${owlY-10}" r="1.5" fill="#222"/>`;
} else {
  svg += `<line x1="${owlX-5}" y1="${owlY-10}" x2="${owlX-1}" y2="${owlY-10}" stroke="#222" stroke-width="1.5" stroke-linecap="round"/>`;
  svg += `<line x1="${owlX+1}" y1="${owlY-10}" x2="${owlX+5}" y2="${owlY-10}" stroke="#222" stroke-width="1.5" stroke-linecap="round"/>`;
}
svg += `<polygon points="${owlX},${owlY-8} ${owlX-1.5},${owlY-6} ${owlX+1.5},${owlY-6}" fill="#DAA520"/>`;
// Owl speech — wisdom sparkles when "talking"
const owlTalk = Math.sin(mt*1.2)>0.5;
if (owlTalk) {
  for (let i = 0; i < 4; i++) {
    const stx = owlX+10+i*5+Math.sin(mt*3+i)*3;
    const sty2 = owlY-12+Math.cos(mt*2+i*1.1)*4;
    svg += `<circle cx="${stx}" cy="${sty2}" r="${1.5-i*0.2}" fill="#FFD700" opacity="${0.4+Math.sin(mt*2+i)*0.3}"/>`;
  }
}

// ── Deer family (right of center, watching curiously) ──
const deX = w*0.72, deY = bY-6;
const deBob = Math.sin(mt*0.6)*2;
// Parent deer
svg += `<ellipse cx="${deX}" cy="${deY+deBob}" rx="16" ry="11" fill="#C4862D" stroke="#A06820" stroke-width="${ol*0.4}"/>`;
svg += `<path d="M${deX+9} ${deY-4+deBob} Q${deX+14} ${deY-16+deBob} ${deX+12} ${deY-26+deBob}" fill="none" stroke="#C4862D" stroke-width="7" stroke-linecap="round"/>`;
svg += `<circle cx="${deX+12}" cy="${deY-30+deBob}" r="5.5" fill="#D4964A" stroke="#A06820" stroke-width="${ol*0.3}"/>`;
svg += `<ellipse cx="${deX+8}" cy="${deY-34+deBob}" rx="2.5" ry="4.5" fill="#C4862D" transform="rotate(-20 ${deX+8} ${deY-34+deBob})"/>`;
svg += `<ellipse cx="${deX+16}" cy="${deY-34+deBob}" rx="2.5" ry="4.5" fill="#C4862D" transform="rotate(20 ${deX+16} ${deY-34+deBob})"/>`;
// Antlers
svg += `<path d="M${deX+9} ${deY-36+deBob} Q${deX+4} ${deY-46} ${deX+2} ${deY-50}" fill="none" stroke="#8B6B4A" stroke-width="1.5" stroke-linecap="round"/>`;
svg += `<path d="M${deX+6} ${deY-43+deBob} Q${deX+4} ${deY-48} ${deX+5} ${deY-52}" fill="none" stroke="#8B6B4A" stroke-width="1.2" stroke-linecap="round"/>`;
svg += `<path d="M${deX+15} ${deY-36+deBob} Q${deX+20} ${deY-46} ${deX+22} ${deY-50}" fill="none" stroke="#8B6B4A" stroke-width="1.5" stroke-linecap="round"/>`;
svg += `<circle cx="${deX+14}" cy="${deY-31+deBob}" r="1.3" fill="#222"/>`;
svg += `<ellipse cx="${deX+16}" cy="${deY-28+deBob}" rx="1.8" ry="1.3" fill="#3A2818"/>`;
for (let i = 0; i < 4; i++) svg += `<line x1="${deX-8+i*6}" y1="${deY+9+deBob}" x2="${deX-8+i*6}" y2="${deY+18}" stroke="#A06820" stroke-width="2.5" stroke-linecap="round"/>`;
// Fawn (baby) peeking from behind parent
const fwX = deX-16, fwY = deY+4;
svg += `<ellipse cx="${fwX}" cy="${fwY+deBob}" rx="9" ry="6" fill="#D4A050" stroke="#A07830" stroke-width="${ol*0.3}"/>`;
svg += `<circle cx="${fwX+5}" cy="${fwY-7+deBob}" r="4" fill="#D4A050" stroke="#A07830" stroke-width="${ol*0.3}"/>`;
svg += `<circle cx="${fwX+7}" cy="${fwY-8+deBob}" r="1" fill="#222"/>`;
for (let i = 0; i < 3; i++) svg += `<circle cx="${fwX-4+i*4}" cy="${fwY-1+deBob}" r="1" fill="#FFF" opacity="0.2"/>`;

// ── THREE PUPS walking along the path (center) ──
const pathY = bY+5;
const walkCycle = mt*0.8;

// Pup 1 (orange, leading)
const p1x2 = w*0.38+Math.sin(walkCycle)*4;
const p1y2 = pathY+Math.abs(Math.sin(walkCycle*2))*2;
svg += `<ellipse cx="${p1x2}" cy="${p1y2-5}" rx="7" ry="5" fill="#FF8C42" stroke="#D06B20" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${p1x2+5}" cy="${p1y2-10}" r="5" fill="#FF8C42" stroke="#D06B20" stroke-width="${ol*0.4}"/>`;
svg += `<polygon points="${p1x2+2},${p1y2-14} ${p1x2+1},${p1y2-19} ${p1x2+5},${p1y2-15}" fill="#E07830"/>`;
svg += `<polygon points="${p1x2+8},${p1y2-14} ${p1x2+9},${p1y2-19} ${p1x2+6},${p1y2-15}" fill="#E07830"/>`;
svg += `<circle cx="${p1x2+4}" cy="${p1y2-11}" r="1" fill="#222"/>`;
svg += `<circle cx="${p1x2+7}" cy="${p1y2-11}" r="1" fill="#222"/>`;
const p1lf = Math.sin(walkCycle*3)*3;
svg += `<line x1="${p1x2-4}" y1="${p1y2-1}" x2="${p1x2-5+p1lf}" y2="${p1y2+5}" stroke="#D06B20" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${p1x2+4}" y1="${p1y2-1}" x2="${p1x2+5-p1lf}" y2="${p1y2+5}" stroke="#D06B20" stroke-width="2" stroke-linecap="round"/>`;
const p1t = Math.sin(mt*3.5)*8;
svg += `<path d="M${p1x2-7} ${p1y2-6} Q${p1x2-12} ${p1y2-14+p1t} ${p1x2-10} ${p1y2-18+p1t*0.5}" fill="none" stroke="#FF8C42" stroke-width="2.5" stroke-linecap="round"/>`;

// Pup 2 (purple, middle)
const p2x2 = p1x2-20+Math.sin(walkCycle+0.5)*3;
const p2y2 = pathY+2+Math.abs(Math.sin(walkCycle*2+1))*2;
svg += `<ellipse cx="${p2x2}" cy="${p2y2-5}" rx="6.5" ry="4.5" fill="#9370DB" stroke="#7B5EA7" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${p2x2+4}" cy="${p2y2-10}" r="4.5" fill="#9370DB" stroke="#7B5EA7" stroke-width="${ol*0.4}"/>`;
svg += `<polygon points="${p2x2+1},${p2y2-14} ${p2x2},${p2y2-19} ${p2x2+4},${p2y2-14}" fill="#8060C0"/>`;
svg += `<polygon points="${p2x2+7},${p2y2-14} ${p2x2+8},${p2y2-19} ${p2x2+5},${p2y2-14}" fill="#8060C0"/>`;
svg += `<circle cx="${p2x2+3}" cy="${p2y2-11}" r="1" fill="#222"/>`;
svg += `<circle cx="${p2x2+6}" cy="${p2y2-11}" r="1" fill="#222"/>`;
const p2lf = Math.sin(walkCycle*3+1)*3;
svg += `<line x1="${p2x2-3}" y1="${p2y2-1}" x2="${p2x2-4+p2lf}" y2="${p2y2+5}" stroke="#7B5EA7" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${p2x2+3}" y1="${p2y2-1}" x2="${p2x2+4-p2lf}" y2="${p2y2+5}" stroke="#7B5EA7" stroke-width="2" stroke-linecap="round"/>`;

// Pup 3 (green, trailing — looking around wide-eyed)
const p3x2 = p2x2-18+Math.sin(walkCycle+1)*3;
const p3y2 = pathY+3+Math.abs(Math.sin(walkCycle*2+2))*2;
svg += `<ellipse cx="${p3x2}" cy="${p3y2-5}" rx="6.5" ry="4.5" fill="#5AAA5A" stroke="#3A8A3A" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${p3x2+4}" cy="${p3y2-10}" r="4.5" fill="#5AAA5A" stroke="#3A8A3A" stroke-width="${ol*0.4}"/>`;
svg += `<polygon points="${p3x2+1},${p3y2-14} ${p3x2},${p3y2-19} ${p3x2+4},${p3y2-14}" fill="#4A9A4A"/>`;
svg += `<polygon points="${p3x2+7},${p3y2-14} ${p3x2+8},${p3y2-19} ${p3x2+5},${p3y2-14}" fill="#4A9A4A"/>`;
svg += `<circle cx="${p3x2+3}" cy="${p3y2-11}" r="1.3" fill="#222"/>`;
svg += `<circle cx="${p3x2+6}" cy="${p3y2-11}" r="1.3" fill="#222"/>`;
// Head turning side to side
const headTurn = Math.sin(mt*1.5)*3;
svg += `<circle cx="${p3x2+4+headTurn}" cy="${p3y2-10}" r="4.5" fill="#5AAA5A" stroke="#3A8A3A" stroke-width="${ol*0.4}"/>`;

// ═══ GOLDEN BUTTERFLY (leading the way) ═══
const bfx2 = w*0.48+Math.sin(mt*0.6)*w*0.08;
const bfy2 = bY-50+Math.cos(mt*0.5)*15;
const bfW2 = Math.sin(mt*7)*5;
svg += `<ellipse cx="${bfx2-3}" cy="${bfy2}" rx="${4+bfW2*0.3}" ry="5" fill="#FFD700" opacity="0.85" transform="rotate(${-bfW2*2} ${bfx2-3} ${bfy2})"/>`;
svg += `<ellipse cx="${bfx2+3}" cy="${bfy2}" rx="${4+bfW2*0.3}" ry="5" fill="#FFD700" opacity="0.85" transform="rotate(${bfW2*2} ${bfx2+3} ${bfy2})"/>`;
svg += `<ellipse cx="${bfx2}" cy="${bfy2}" rx="1" ry="3.5" fill="#8B6914"/>`;
for (let i = 0; i < 6; i++) {
  const trx = bfx2-i*4-Math.sin(mt*0.5+i*0.3)*3;
  const tri2 = bfy2+i*1.5+Math.cos(mt*0.6+i*0.4)*2;
  svg += `<circle cx="${trx}" cy="${tri2}" r="${1.8-i*0.2}" fill="#FFD700" opacity="${0.25-i*0.03}"/>`;
}
svg += `<circle cx="${bfx2}" cy="${bfy2}" r="${10+w3*5}" fill="#FFD700" opacity="${0.04+w1*0.03}"/>`;

// ── Fireflies ──
for (let i = 0; i < 15; i++) {
  const ffx = (Math.sin(i*47.3+3.1)*0.5+0.5)*w;
  const ffy = bY-35+(Math.sin(i*83.7+7.3)*0.5+0.5)*55;
  const ffD = Math.sin(mt*0.7+i*0.97)*10;
  const ffU = Math.cos(mt*0.5+i*1.3)*7;
  const ffop = 0.2+Math.sin(mt*2+i*1.1)*0.3;
  svg += `<circle cx="${ffx+ffD}" cy="${ffy+ffU}" r="${1.3+Math.sin(mt*1.5+i*0.8)*0.6}" fill="${sc.acc}" opacity="${ffop}"/>`;
  svg += `<circle cx="${ffx+ffD}" cy="${ffy+ffU}" r="${4+Math.sin(mt*1.5+i)*2}" fill="${sc.acc}" opacity="${ffop*0.08}"/>`;
}

// ── Butterflies (companions) ──
for (let i = 0; i < 2; i++) {
  const btx = w*(0.5+i*0.25)+Math.sin(mt*0.6+i*2.1)*30;
  const bty2 = bY-25-i*15+Math.cos(mt*0.5+i*1.7)*12;
  const wF = Math.sin(mt*6+i*3)*5;
  const btC = i===0?'#FF69B4':'#87CEEB';
  svg += `<ellipse cx="${btx-2}" cy="${bty2}" rx="${3+wF*0.3}" ry="3.5" fill="${btC}" opacity="0.7" transform="rotate(${-wF*2} ${btx-2} ${bty2})"/>`;
  svg += `<ellipse cx="${btx+2}" cy="${bty2}" rx="${3+wF*0.3}" ry="3.5" fill="${btC}" opacity="0.7" transform="rotate(${wF*2} ${btx+2} ${bty2})"/>`;
  svg += `<ellipse cx="${btx}" cy="${bty2}" rx="0.8" ry="2.5" fill="#333"/>`;
}

if (isN) {
  svg += `<circle cx="${w*0.5}" cy="${h*0.06}" r="14" fill="#EDE8DF" opacity="0.7"/>`;
  svg += `<circle cx="${w*0.5+4}" cy="${h*0.06-3}" r="11" fill="#0A0520" opacity="0.9"/>`;
}
